use anyhow::Context;
use clap::{Parser, Subcommand};
use client::{print, Client};
use den_core::*;
use reqwest::Method;
use std::path::PathBuf;

#[derive(Parser)]
#[command(
    name = "den",
    version,
    about = "Talk to a Den server; command results are JSON"
)]
struct Cli {
    #[arg(
        long,
        env = "DEN_URL",
        default_value = "http://127.0.0.1:7000",
        global = true
    )]
    url: String,
    #[arg(long, env = "DEN_TOKEN", global = true, hide_env_values = true)]
    token: Option<String>,
    #[arg(long, env = "DEN_CONFIG", global = true)]
    config: Option<PathBuf>,
    #[command(subcommand)]
    cmd: Cmd,
}
#[derive(Subcommand)]
enum Cmd {
    Health,
    #[command(subcommand)]
    Host(hosts::HostCmd),
    #[command(subcommand)]
    Access(hosts::AccessCmd),
    #[command(subcommand)]
    Terminal(hosts::TerminalCmd),
    #[command(subcommand)]
    Canvas(canvas::Cmd),
    /// Claim a new local instance using its one-time key file.
    Init {
        username: String,
        #[arg(long, default_value = "data/bootstrap.key")]
        bootstrap_file: PathBuf,
        #[arg(long)]
        password_stdin: bool,
    },
    Login {
        username: String,
        #[arg(long)]
        password_stdin: bool,
    },
    Register {
        username: String,
        #[arg(long, env = "DEN_INVITE", hide_env_values = true)]
        invite: String,
        #[arg(long)]
        password_stdin: bool,
    },
    Logout,
    Me,
    Users,
    Channels,
    #[command(subcommand)]
    Channel(ChannelCmd),
    #[command(subcommand)]
    Category(CategoryCmd),
    #[command(subcommand)]
    Invite(InviteCmd),
    /// Create or reopen a DM with the exact member set, including yourself.
    Dm {
        /// User ULIDs or @usernames. Your own user is included automatically.
        members: Vec<String>,
    },
    Send {
        /// Channel ULID, text channel name (general or #general), or @username for a DM.
        channel: String,
        text: String,
        #[arg(long)]
        reply_to: Option<String>,
        #[arg(long = "upload")]
        uploads: Vec<String>,
    },
    Read {
        /// Channel ULID, text channel name (general or #general), or @username for a DM.
        channel: String,
        #[arg(long)]
        before: Option<String>,
        #[arg(long)]
        after: Option<String>,
        #[arg(long, default_value_t = 50)]
        limit: u32,
        /// Fetch every matching page and print one ascending, de-duplicated array.
        #[arg(long)]
        all: bool,
    },
    Edit {
        message: String,
        text: String,
    },
    Delete {
        message: String,
    },
    /// Print events as JSON lines; reconnects report gaps requiring a fresh read.
    Tail {
        /// Channel ULID, text channel name (general or #general), or @username for a DM.
        channel: Option<String>,
    },
    /// Upload a file; use the printed ID with --resume after interruption.
    Upload {
        /// Channel ULID, text channel name (general or #general), or @username for a DM.
        channel: String,
        file: PathBuf,
        #[arg(long)]
        resume: Option<String>,
        #[arg(long)]
        content_type: Option<String>,
    },
    #[command(subcommand)]
    Token(TokenCmd),
    #[command(subcommand)]
    Bot(BotCmd),
}
#[derive(Subcommand)]
enum ChannelCmd {
    Create {
        name: String,
        #[arg(long)]
        category: Option<String>,
        #[arg(long, default_value_t = 0)]
        position: i64,
    },
    Update {
        /// Channel ULID, text channel name (general or #general), or @username for a DM.
        #[arg(value_name = "CHANNEL")]
        id: String,
        name: String,
        #[arg(long)]
        category: Option<String>,
        #[arg(long, default_value_t = 0)]
        position: i64,
    },
    Delete {
        /// Channel ULID, text channel name (general or #general), or @username for a DM.
        #[arg(value_name = "CHANNEL")]
        id: String,
    },
}
#[derive(Subcommand)]
enum CategoryCmd {
    List,
    Create {
        name: String,
        #[arg(long, default_value_t = 0)]
        position: i64,
    },
    Update {
        id: String,
        name: String,
        #[arg(long, default_value_t = 0)]
        position: i64,
    },
    Delete {
        id: String,
    },
}
#[derive(Subcommand)]
enum InviteCmd {
    Create {
        #[arg(long, default_value_t = 1)]
        uses: u32,
        #[arg(long, default_value_t = 24)]
        hours: u32,
    },
    Revoke {
        id: String,
    },
}
#[derive(Subcommand)]
enum TokenCmd {
    Create {
        name: String,
        #[arg(long)]
        user: Option<String>,
    },
    List,
    Revoke {
        id: String,
    },
}
#[derive(Subcommand)]
enum BotCmd {
    Create {
        username: String,
        #[arg(long)]
        display_name: Option<String>,
    },
}
fn password(stdin: bool) -> anyhow::Result<String> {
    if let Ok(value) = std::env::var("DEN_PASSWORD") {
        return Ok(value);
    }
    anyhow::ensure!(stdin, "Set DEN_PASSWORD or pass --password-stdin");
    let mut value = String::new();
    std::io::stdin().read_line(&mut value)?;
    Ok(value.trim_end_matches(['\r', '\n']).to_string())
}
fn id(value: &str) -> anyhow::Result<&str> {
    anyhow::ensure!(
        value.len() == 26 && value.bytes().all(|b| b.is_ascii_alphanumeric()),
        "Expected a ULID"
    );
    Ok(value)
}
fn validate_read(limit: u32, before: Option<&str>, after: Option<&str>) -> anyhow::Result<()> {
    anyhow::ensure!((1..=200).contains(&limit), "Limit must be 1-200");
    anyhow::ensure!(
        before.is_none() || after.is_none(),
        "Use before or after, not both"
    );
    if let Some(v) = before {
        id(v)?;
    }
    if let Some(v) = after {
        id(v)?;
    }
    Ok(())
}
/// Fetch every matching message page. Backward walks (no cursor or `before`)
/// start at the newest page and page toward older IDs; forward walks (`after`)
/// start at the oldest page after the cursor and page toward newer IDs.
/// Results are de-duplicated and returned in ascending message-ID order.
fn read_all(
    c: &Client,
    channel_id: &str,
    before: Option<String>,
    after: Option<String>,
    limit: u32,
) -> anyhow::Result<Vec<Message>> {
    read_all_pages(before, after, limit, |before, after| {
        let mut path = format!("/channels/{channel_id}/messages?limit={limit}");
        if let Some(v) = before {
            path.push_str(&format!("&before={v}"));
        }
        if let Some(v) = after {
            path.push_str(&format!("&after={v}"));
        }
        c.get(&path)
    })
}
fn read_all_pages(
    before: Option<String>,
    after: Option<String>,
    limit: u32,
    mut fetch: impl FnMut(Option<&str>, Option<&str>) -> anyhow::Result<Vec<Message>>,
) -> anyhow::Result<Vec<Message>> {
    use std::collections::BTreeMap;
    let forward = after.is_some();
    let mut cursor_before = before;
    let mut cursor_after = after;
    let mut collected: BTreeMap<String, Message> = BTreeMap::new();
    loop {
        let page = fetch(cursor_before.as_deref(), cursor_after.as_deref())?;
        let full = page.len() == limit as usize;
        let fresh = page
            .iter()
            .any(|message| !collected.contains_key(&message.id));
        // Pages arrive ascending: the walk edge is the oldest message going
        // backwards, the newest going forwards.
        let edge = if forward { page.last() } else { page.first() }.map(|m| m.id.clone());
        for message in page {
            collected.insert(message.id.clone(), message);
        }
        if !full {
            break;
        }
        let edge = edge.expect("a full page is non-empty");
        let prev = if forward { &cursor_after } else { &cursor_before };
        let progressed = match prev {
            Some(prev) if forward => edge > *prev,
            Some(prev) => edge < *prev,
            None => true,
        };
        anyhow::ensure!(
            fresh && progressed,
            "Message pages stopped progressing at message {edge}"
        );
        if forward {
            cursor_after = Some(edge);
        } else {
            cursor_before = Some(edge);
        }
    }
    Ok(collected.into_values().collect())
}
fn main() -> anyhow::Result<()> {
    let args = Cli::parse();
    let mut c = Client::new(args.url, args.token, args.config)?;
    match args.cmd {
        Cmd::Canvas(cmd) => canvas::run(&c, cmd)?,
        Cmd::Host(cmd) => hosts::host(&c, cmd)?,
        Cmd::Access(cmd) => hosts::access(&c, cmd)?,
        Cmd::Terminal(cmd) => hosts::terminal(&c, cmd)?,
        Cmd::Health => print(&c.get::<Health>("/health")?)?,
        Cmd::Init {
            username,
            bootstrap_file,
            password_stdin,
        } => {
            let session: Session = c.send(
                Method::POST,
                "/auth/init",
                &Bootstrap {
                    username,
                    password: password(password_stdin)?,
                    bootstrap_token: std::fs::read_to_string(bootstrap_file)
                        .context("Read the bootstrap key on the server machine")?,
                },
            )?;
            print(&session.user)?;
            c.save(session)?;
        }
        Cmd::Login {
            username,
            password_stdin,
        } => {
            let session: Session = c.send(
                Method::POST,
                "/auth/login",
                &Login {
                    username,
                    password: password(password_stdin)?,
                },
            )?;
            print(&session.user)?;
            c.save(session)?;
        }
        Cmd::Register {
            username,
            invite,
            password_stdin,
        } => {
            let session: Session = c.send(
                Method::POST,
                "/auth/register",
                &Register {
                    username,
                    password: password(password_stdin)?,
                    invite,
                },
            )?;
            print(&session.user)?;
            c.save(session)?;
        }
        Cmd::Logout => {
            c.empty(Method::POST, "/auth/logout")?;
            c.forget()?;
        }
        Cmd::Me => print(&c.get::<User>("/users/me")?)?,
        Cmd::Users => print(&c.get::<Vec<User>>("/users")?)?,
        Cmd::Channels => print(&c.get::<Vec<Channel>>("/channels")?)?,
        Cmd::Channel(v) => match v {
            ChannelCmd::Create {
                name,
                category,
                position,
            } => print(&c.send::<Channel>(
                Method::POST,
                "/channels",
                &SaveChannel {
                    name,
                    category_id: category,
                    position,
                },
            )?)?,
            ChannelCmd::Update {
                id: cid,
                name,
                category,
                position,
            } => print(&c.send::<Channel>(
                Method::PUT,
                &format!("/channels/{}", c.resolve_channel(&cid)?),
                &SaveChannel {
                    name,
                    category_id: category,
                    position,
                },
            )?)?,
            ChannelCmd::Delete { id: cid } => c.empty(
                Method::DELETE,
                &format!("/channels/{}", c.resolve_channel(&cid)?),
            )?,
        },
        Cmd::Category(v) => match v {
            CategoryCmd::List => print(&c.get::<Vec<Category>>("/categories")?)?,
            CategoryCmd::Create { name, position } => print(&c.send::<Category>(
                Method::POST,
                "/categories",
                &SaveCategory { name, position },
            )?)?,
            CategoryCmd::Update {
                id: cid,
                name,
                position,
            } => print(&c.send::<Category>(
                Method::PUT,
                &format!("/categories/{}", id(&cid)?),
                &SaveCategory { name, position },
            )?)?,
            CategoryCmd::Delete { id: cid } => {
                c.empty(Method::DELETE, &format!("/categories/{}", id(&cid)?))?
            }
        },
        Cmd::Invite(v) => match v {
            InviteCmd::Create { uses, hours } => print(&c.send::<Invite>(
                Method::POST,
                "/invites",
                &CreateInvite {
                    uses,
                    expires_in_hours: hours,
                },
            )?)?,
            InviteCmd::Revoke { id: cid } => {
                c.empty(Method::DELETE, &format!("/invites/{}", id(&cid)?))?
            }
        },
        Cmd::Dm { members } => print(&c.dm(&members)?)?,
        Cmd::Send {
            channel,
            text,
            reply_to,
            uploads,
        } => print(&c.send::<Message>(
            Method::POST,
            &format!("/channels/{}/messages", c.resolve_channel(&channel)?),
            &CreateMessage {
                content: text,
                reply_to,
                upload_ids: uploads,
            },
        )?)?,
        Cmd::Read {
            channel,
            before,
            after,
            limit,
            all,
        } => {
            validate_read(limit, before.as_deref(), after.as_deref())?;
            let channel_id = c.resolve_channel(&channel)?;
            if !all {
                let mut path = format!("/channels/{channel_id}/messages?limit={limit}");
                if let Some(v) = before {
                    path.push_str(&format!("&before={}", id(&v)?));
                }
                if let Some(v) = after {
                    path.push_str(&format!("&after={}", id(&v)?));
                }
                print(&c.get::<Vec<Message>>(&path)?)?;
            } else {
                print(&read_all(&c, &channel_id, before, after, limit)?)?;
            }
        }
        Cmd::Edit { message, text } => print(&c.send::<Message>(
            Method::PATCH,
            &format!("/messages/{}", id(&message)?),
            &EditMessage { content: text },
        )?)?,
        Cmd::Delete { message } => {
            c.empty(Method::DELETE, &format!("/messages/{}", id(&message)?))?
        }
        Cmd::Tail { channel } => {
            let channel = channel
                .as_deref()
                .map(|v| c.resolve_channel(v))
                .transpose()?;
            stream::tail(&c, channel)?;
        }
        Cmd::Upload {
            channel,
            file,
            resume,
            content_type,
        } => stream::upload(
            &c,
            &c.resolve_channel(&channel)?,
            &file,
            resume,
            content_type,
        )?,
        Cmd::Token(v) => match v {
            TokenCmd::Create { name, user } => print(&c.send::<TokenSecret>(
                Method::POST,
                "/tokens",
                &CreateToken {
                    name,
                    user_id: user,
                },
            )?)?,
            TokenCmd::List => print(&c.get::<Vec<Token>>("/tokens")?)?,
            TokenCmd::Revoke { id: tid } => {
                c.empty(Method::DELETE, &format!("/tokens/{}", id(&tid)?))?
            }
        },
        Cmd::Bot(BotCmd::Create {
            username,
            display_name,
        }) => print(&c.send::<BotCreated>(
            Method::POST,
            "/bots",
            &CreateBot {
                display_name: display_name.unwrap_or_else(|| username.clone()),
                username,
            },
        )?)?,
    }
    Ok(())
}
#[cfg(test)]
mod tests {
    use super::*;
    use clap::Parser;
    fn msg(n: u64) -> Message {
        Message {
            id: format!("{n:026}"),
            channel_id: "01CHANNEL000000000000000".into(),
            author_id: "01AUTHOR0000000000000000".into(),
            content: format!("m{n}"),
            reply_to: None,
            created_at: String::new(),
            edited_at: None,
            attachments: Vec::new(),
            objects: Vec::new(),
            reactions: Vec::new(),
            mention_ids: Vec::new(),
        }
    }
    fn ids(messages: &[Message]) -> Vec<u64> {
        messages.iter().map(|m| m.id.parse().unwrap()).collect()
    }
    /// Simulates the server over message IDs 1..=total, recording cursors.
    fn server(
        total: u64,
        limit: u32,
        calls: std::rc::Rc<std::cell::RefCell<Vec<(Option<String>, Option<String>)>>>,
    ) -> impl FnMut(Option<&str>, Option<&str>) -> anyhow::Result<Vec<Message>> {
        move |before, after| {
            calls
                .borrow_mut()
                .push((before.map(str::to_string), after.map(str::to_string)));
            let matching = (1..=total).filter(|i| {
                let id = format!("{i:026}");
                before.is_none_or(|b| id.as_str() < b) && after.is_none_or(|a| id.as_str() > a)
            });
            let page: Vec<u64> = if after.is_some() {
                matching.take(limit as usize).collect()
            } else {
                let mut page: Vec<u64> = matching.rev().take(limit as usize).collect();
                page.reverse();
                page
            };
            Ok(page.into_iter().map(msg).collect())
        }
    }
    #[test]
    fn read_parses_all_flag() {
        let cli = Cli::try_parse_from(["den", "read", "general", "--all"]).unwrap();
        let Cmd::Read { all, limit, .. } = cli.cmd else {
            panic!("expected read")
        };
        assert!(all);
        assert_eq!(limit, 50);
    }
    #[test]
    fn read_all_walks_backwards_from_newest() {
        let calls = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let messages = read_all_pages(None, None, 100, server(250, 100, calls.clone())).unwrap();
        assert_eq!(ids(&messages), (1..=250).collect::<Vec<_>>());
        let calls = calls.borrow();
        assert_eq!(calls.len(), 3);
        assert_eq!(calls[0], (None, None));
        assert_eq!(calls[1].0.as_deref(), Some(&msg(151).id[..]));
        assert_eq!(calls[2].0.as_deref(), Some(&msg(51).id[..]));
    }
    #[test]
    fn read_all_walks_forwards_from_after() {
        let calls = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let start = msg(100).id;
        let messages =
            read_all_pages(None, Some(start.clone()), 100, server(250, 100, calls.clone()))
                .unwrap();
        assert_eq!(ids(&messages), (101..=250).collect::<Vec<_>>());
        let calls = calls.borrow();
        assert_eq!(calls.len(), 2);
        assert_eq!(calls[0], (None, Some(start)));
        assert_eq!(calls[1].1.as_deref(), Some(&msg(200).id[..]));
    }
    #[test]
    fn read_all_includes_the_final_short_page() {
        // 7 messages at limit 3: pages of 3, 3, then a short page of 1.
        let calls = std::rc::Rc::new(std::cell::RefCell::new(Vec::new()));
        let messages = read_all_pages(None, None, 3, server(7, 3, calls)).unwrap();
        assert_eq!(ids(&messages), (1..=7).collect::<Vec<_>>());
    }
    #[test]
    fn read_all_dedupes_overlapping_pages() {
        let mut pages = vec![vec![msg(1), msg(2), msg(3)], vec![msg(1)]].into_iter();
        let messages =
            read_all_pages(None, None, 3, move |_, _| Ok(pages.next().unwrap_or_default()))
                .unwrap();
        assert_eq!(ids(&messages), vec![1, 2, 3]);
    }
    #[test]
    fn read_all_fails_when_pages_stop_progressing() {
        // A full page repeating forever must fail, not hang.
        let result = read_all_pages(None, None, 3, |_, _| Ok(vec![msg(1), msg(2), msg(3)]));
        assert!(result.is_err());
        // An edge that repeats the cursor violates exclusivity; also a failure.
        let cursor = msg(5).id;
        let result = read_all_pages(None, Some(cursor), 2, |_, _| Ok(vec![msg(4), msg(5)]));
        assert!(result.is_err());
    }
    #[test]
    fn read_all_propagates_page_errors() {
        let result = read_all_pages(None, None, 3, |_, _| anyhow::bail!("first page failed"));
        assert!(result.is_err());
        let mut first = true;
        let result = read_all_pages(None, None, 3, move |_, _| {
            if std::mem::replace(&mut first, false) {
                Ok(vec![msg(1), msg(2), msg(3)])
            } else {
                anyhow::bail!("later page failed")
            }
        });
        assert!(result.is_err());
    }
    #[test]
    fn validate_read_rejects_before_any_request() {
        for (limit, before, after) in [
            (0, None, None),
            (201, None, None),
            (
                50,
                Some("01ARZ3NDEKTSV4RRFFQ69G5FAV"),
                Some("01ARZ3NDEKTSV4RRFFQ69G5FAV"),
            ),
            (50, Some("not-a-ulid"), None),
            (50, None, Some("not-a-ulid")),
        ] {
            assert!(validate_read(limit, before, after).is_err());
        }
        assert!(validate_read(1, None, None).is_ok());
        assert!(validate_read(200, Some("01ARZ3NDEKTSV4RRFFQ69G5FAV"), None).is_ok());
    }
}

